// generated by `cargo xtask protocol` from crates/kiln-protocol, do not edit
import type { GridFlashCell } from "./GridFlashCell";
import type { GridGoalSeekStatus } from "./GridGoalSeekStatus";
import type { GridPivotInfo } from "./GridPivotInfo";
import type { GridSheetPermissions } from "./GridSheetPermissions";
import type { GridSparkInfo } from "./GridSparkInfo";

/**
 * The analysis part of the chrome's state.
 */
export type GridAnalysisState = { 
/**
 * The PivotTable at the active cell.
 */
pivot: GridPivotInfo | null, 
/**
 * The sparkline group at the active cell.
 */
sparkline: GridSparkInfo | null, 
/**
 * The last Goal Seek.
 */
goal_seek: GridGoalSeekStatus | null, 
/**
 * Flash Fill's suggestions for the column of the last entry (Enter accepts them).
 */
flash: Array<GridFlashCell>, 
/**
 * How many cells the suggestions fill.
 */
flash_count: number, 
/**
 * The active sheet is protected.
 */
sheet_protected: boolean, 
/**
 * Its protection has a password.
 */
sheet_password: boolean, 
/**
 * Its permissions.
 */
permissions: GridSheetPermissions, 
/**
 * The workbook structure is protected.
 */
workbook_protected: boolean, 
/**
 * Its protection has a password.
 */
workbook_password: boolean, 
/**
 * The active cell is locked (Format ▸ Lock Cell).
 */
locked: boolean, 
/**
 * A message box to show (a refused edit of a protected sheet or PivotTable).
 */
alert: string | null, 
/**
 * Counts the message boxes raised, so a repeated refusal shows again.
 */
alert_seq: number, 
/**
 * The workbook theme's name.
 */
theme: string, 
/**
 * An empty PivotTable on the active sheet: its name and the placeholder's rectangle (x,
 * y, width, height in surface CSS pixels), where the chrome writes Excel's prompt.
 */
placeholder: [string, [number, number, number, number]] | null, };
